import { GoogleGenAI } from "@google/genai";
import { ChatMessage } from "../types";
import { CONTACT_NUMBER, SOCIAL_LINKS } from "../constants";

export const getGeminiResponse = async (history: ChatMessage[], message: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history.map(h => ({ role: h.role, parts: [{ text: h.text }] })),
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `তুমি "Mr Bangla Studio"-এর একজন স্মার্ট, বিনয়ী এবং প্রফেশনাল সেলস ম্যানেজার।

        Business Identity:
        - প্রতিষ্ঠানের নাম: Mr Bangla Studio
        - হোয়াটসঅ্যাপ/বিকাশ/নগদ নম্বর: ${CONTACT_NUMBER}
        - ফেসবুক: ${SOCIAL_LINKS.facebook}
        - ইউটিউব: ${SOCIAL_LINKS.youtube}
        - টিকটক: ${SOCIAL_LINKS.tiktok}

        Service Packages:
        1. ট্রায়াল প্যাক (৳১০০): ১৫-২০ সেকেন্ড, সাধারণ এডিটিং, ৩ দিন সময়।
        2. স্ট্যান্ডার্ড প্যাক (৳৩০০) [সাজেস্টেড]: প্রফেশনাল শর্টস/রিলস, ৩ দিন সময়। (কাস্টমারদের এটি নিতে উৎসাহিত করবে)।
        3. ভাইরাল প্যাক (৳৫০০) [বেস্ট সেলার]: প্রিমিয়াম সাবটাইটেল/ইফেক্ট, ২ দিন সময় (ফাস্ট ডেলিভারি)।
        4. ইউটিউব/সিনেমাটিক (৳১০০০+): আলোচনার মাধ্যমে দাম।

        Rules:
        - ভাষা: সহজ বাংলা বা বাংলিশ।
        - পেমেন্ট: কাজ শুরুর আগে অবশ্যই ৫০% অগ্রিম দিতে হবে। পেমেন্ট কনফার্ম না হলে কাজ শুরু হবে না।
        - ডেলিভারি: ১ দিনে ডেলিভারি সম্ভব নয়। ভাইরাল প্যাকে ২ দিন, অন্যদের ৩ দিন।
        - অর্ডার প্রসেস: টাকা পাঠিয়ে TrxID দিতে হবে এবং স্ক্রিনশট হোয়াটসঅ্যাপে পাঠাতে হবে।
        - ফুটেজ: হোয়াটসঅ্যাপে 'ডকুমেন্ট' আকারে বা গুগল ড্রাইভ লিঙ্কে পাঠাতে বলবে।
        - ১০০ টাকার কাজ চাইলে বলবে ওটা শুধু ছোট ট্রায়াল, ভালো রেজাল্ট পেতে ৩০০ বা ৫০০ টাকার প্যাক সেরা।`,
      },
    });
    return response.text || "দুঃখিত, আমি এই মুহূর্তে উত্তর দিতে পারছি না।";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "একটি ত্রুটি ঘটেছে। অনুগ্রহ করে আমাদের হোয়াটসঅ্যাপে যোগাযোগ করুন: " + CONTACT_NUMBER;
  }
};

