export type ServiceType = 'TRIAL' | 'STANDARD' | 'VIRAL' | 'CINEMATIC';

export interface PricingPlan {
  id: ServiceType;
  title: string;
  price: number;
  description: string;
  deliveryTime: string;
  features: string[];
  badge?: string;
}

export interface OrderDetails {
  serviceType: ServiceType;
  duration: number; // in minutes
  instructions: string;
  trxId: string;
  paymentMethod: 'BKASH' | 'NAGAD';
  paymentType: 'FULL' | 'ADVANCE'; 
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

import React, { useState, useEffect, useRef } from 'react';
import { createRoot } from 'react-dom/client';
import { PRICING_PLANS, PAYMENT_METHODS, CONTACT_NUMBER, SOCIAL_LINKS } from './constants';
import { ServiceType, OrderDetails, ChatMessage } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'home' | 'order' | 'pricing'>('home');
  const [selectedPlan, setSelectedPlan] = useState<ServiceType | null>(null);
  const [orderDetails, setOrderDetails] = useState<Partial<OrderDetails>>({
    paymentMethod: 'BKASH',
    paymentType: 'ADVANCE',
  });
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState('');
  const [isChatLoading, setIsChatLoading] = useState(false);
  const [isOrderSubmitted, setIsOrderSubmitted] = useState(false);

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory]);

  const handleSendMessage = async () => {
    if (!userInput.trim()) return;

    const newUserMsg: ChatMessage = { role: 'user', text: userInput };
    setChatHistory(prev => [...prev, newUserMsg]);
    setUserInput('');
    setIsChatLoading(true);

    const response = await getGeminiResponse(chatHistory, userInput);
    const aiMsg: ChatMessage = { role: 'model', text: response };
    setChatHistory(prev => [...prev, aiMsg]);
    setIsChatLoading(false);
  };

  const getPrice = () => {
    const plan = PRICING_PLANS.find(p => p.id === selectedPlan);
    return plan?.price || 0;
  };

  const totalAmount = getPrice();
  const payableAmount = orderDetails.paymentType === 'ADVANCE' ? totalAmount * 0.5 : totalAmount;

  const handleOrderSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const plan = PRICING_PLANS.find(p => p.id === selectedPlan);

    const waMessage = `আসসালামু আলাইকুম Mr Bangla Studio,
আমি একটি অর্ডার করতে চাই।

📌 অর্ডার ডিটেইলস:
প্যাকেজ: ${plan?.title}
মূল্য: ৳${totalAmount}
পেমেন্ট মেথড: ${orderDetails.paymentMethod}
TrxID: ${orderDetails.trxId || 'N/A'}
পেমেন্ট টাইপ: ${orderDetails.paymentType === 'ADVANCE' ? '৫০% অগ্রিম' : 'ফুল পেমেন্ট'}

নিচে আমি পেমেন্ট স্ক্রিনশট এবং ফুটেজগুলো (ডকুমেন্ট আকারে) পাঠিয়ে দিচ্ছি।`;

    const encodedMsg = encodeURIComponent(waMessage);
    const waUrl = `https://wa.me/88${CONTACT_NUMBER.replace('-', '')}?text=${encodedMsg}`;

    window.open(waUrl, '_blank');
    setIsOrderSubmitted(true);
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-100 selection:bg-indigo-500/30">
      {/* Animated Background Orbs */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-600/10 blur-[120px] rounded-full animate-pulse" />
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-rose-600/10 blur-[120px] rounded-full animate-pulse" style={{ animationDelay: '2s' }} />
      </div>

      {/* Navigation */}
      <nav className="sticky top-0 z-50 glass-panel border-b border-white/5 px-6 py-4 flex justify-between items-center">
        <div className="flex items-center gap-3 group cursor-pointer" onClick={() => setActiveTab('home')}>
          <div className="bg-gradient-to-tr from-indigo-500 to-rose-500 p-2 rounded-xl rotate-3 group-hover:rotate-12 transition-transform shadow-lg shadow-indigo-500/20">
            <span className="text-2xl">🎬</span>
          </div>
          <div className="text-2xl font-black gradient-text tracking-tighter">Mr Bangla Studio</div>
        </div>
        <div className="hidden md:flex gap-1 bg-slate-900/50 p-1 rounded-2xl border border-white/5">
          {[
            { id: 'home', label: 'হোম' },
            { id: 'pricing', label: 'প্যাকেজ' },
            { id: 'order', label: 'অর্ডার' }
          ].map(tab => (
            <button 
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)} 
              className={`px-6 py-2 rounded-xl text-sm font-bold transition-all ${activeTab === tab.id ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/30' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
            >
              {tab.label}
            </button>
          ))}
        </div>
        <a 
          href={`https://wa.me/88${CONTACT_NUMBER.replace('-', '')}`} 
          target="_blank"
          className="bg-green-600 hover:bg-green-700 px-6 py-2.5 rounded-2xl text-xs font-black transition-all transform hover:scale-105 shadow-xl shadow-green-600/20 flex items-center gap-2"
        >
          <span className="text-lg">💬</span> হোয়াটসঅ্যাপ
        </a>
      </nav>

      <main className="relative flex-grow max-w-7xl mx-auto px-4 py-12 w-full">
        {activeTab === 'home' && (
          <div className="space-y-24">
            <section className="pt-20 pb-12 text-center animate-fade-in">
              <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full border border-indigo-500/20 bg-indigo-500/5 text-indigo-400 text-xs font-black mb-8 uppercase tracking-widest">
                <span className="h-2 w-2 bg-indigo-500 rounded-full animate-ping" />
                Premium Video Editing Service
              </div>
              <h1 className="text-6xl md:text-9xl font-black mb-8 leading-[0.9] tracking-tighter">
                আপনার ভিডিওকে দিন <br />
                <span className="gradient-text italic">সুপার ভাইরাল</span> লুক
              </h1>
              <p className="text-slate-400 text-lg md:text-xl max-w-2xl mx-auto mb-12 font-medium">
                Mr Bangla Studio-তে আমরা আপনার ভিডিওর জন্য প্রফেশনাল সাবটাইটেল, ট্রেন্ডি ট্রানজিশন এবং পাওয়ারফুল সাউন্ড ডিজাইন নিশ্চিত করি।
              </p>
              <div className="flex flex-wrap justify-center gap-6">
                <button 
                  onClick={() => setActiveTab('pricing')}
                  className="bg-indigo-600 hover:bg-indigo-700 text-white px-12 py-6 rounded-[2rem] text-xl font-black transition-all transform hover:scale-105 shadow-2xl shadow-indigo-600/30 flex items-center gap-3"
                >
                  প্যাকেজ দেখুন 🚀
                </button>
                <button 
                  onClick={() => setActiveTab('order')}
                  className="bg-slate-800/50 hover:bg-slate-800 text-white px-12 py-6 rounded-[2rem] text-xl font-black transition-all border border-white/5"
                >
                  অর্ডার দিন
                </button>
              </div>
            </section>

            <section className="grid md:grid-cols-4 gap-8">
              {[
                { title: 'ভাইরাল এডিটিং', desc: 'ট্রেন্ডি ক্যাপশন ও কাস্টম ইফেক্ট।', icon: '🎨', color: 'from-orange-500 to-rose-500' },
                { title: '২ দিনের ডেলিভারি', desc: 'দ্রুত এবং প্রফেশনাল কোয়ালিটি।', icon: '⚡', color: 'from-blue-500 to-indigo-500' },
                { title: 'সিকিউর পেমেন্ট', desc: 'বিকাশ ও নগদে অগ্রিম ব্যবস্থা।', icon: '🛡️', color: 'from-green-500 to-emerald-500' },
                { title: 'সরাসরি সাপোর্ট', desc: 'হোয়াটসঅ্যাপে সরাসরি যোগাযোগ।', icon: '📱', color: 'from-purple-500 to-violet-500' }
              ].map((item, i) => (
                <div key={i} className="group glass-panel p-10 rounded-[2.5rem] border-white/5 hover:border-indigo-500/30 transition-all transform hover:-translate-y-2">
                  <div className={`w-16 h-16 rounded-2xl bg-gradient-to-tr ${item.color} flex items-center justify-center text-3xl mb-6 shadow-lg group-hover:rotate-6 transition-transform`}>
                    {item.icon}
                  </div>
                  <h3 className="text-2xl font-black mb-3">{item.title}</h3>
                  <p className="text-slate-500 text-sm font-medium leading-relaxed">{item.desc}</p>
                </div>
              ))}
            </section>
          </div>
        )}

        {activeTab === 'pricing' && (
          <div className="space-y-16 animate-fade-in">
            <div className="text-center space-y-4">
              <h2 className="text-5xl md:text-7xl font-black tracking-tighter">সেরা <span className="gradient-text">প্যাকেজ</span> বেছে নিন</h2>
              <p className="text-slate-400 text-lg font-medium">আপনার বাজেটে সেরা কোয়ালিটি নিশ্চিত করছি আমরা</p>
            </div>
            <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-8">
              {PRICING_PLANS.map((plan) => (
                <div key={plan.id} className={`glass-panel p-10 rounded-[3rem] flex flex-col relative overflow-hidden transition-all hover:scale-[1.05] group ${plan.badge ? 'border-indigo-500/40 bg-indigo-500/5 shadow-2xl shadow-indigo-500/10' : 'border-white/5'}`}>
                  {plan.badge && (
                    <div className="absolute top-0 right-0 bg-indigo-600 text-[10px] font-black px-6 py-2 rounded-bl-3xl uppercase tracking-widest shadow-lg">
                      {plan.badge}
                    </div>
                  )}
                  <div className="mb-8">
                    <h3 className="text-xl font-black text-indigo-400 uppercase tracking-widest mb-4">{plan.title}</h3>
