                  </div>
                  <p className="text-sm text-slate-400 mb-10 font-medium leading-relaxed flex-grow">{plan.description}</p>
                  <ul className="space-y-4 mb-10">
                    {plan.features.map((f, i) => (
                      <li key={i} className="text-sm flex items-center gap-3 font-bold text-slate-300">
                        <div className="h-5 w-5 rounded-full bg-indigo-500/20 flex items-center justify-center text-indigo-400 text-[8px]">✓</div>
                        {f}
                      </li>
                    ))}
                  </ul>
                  <button 
                    onClick={() => { setSelectedPlan(plan.id); setActiveTab('order'); }}
                    className={`w-full py-5 rounded-[2rem] transition-all font-black text-lg ${plan.badge ? 'bg-indigo-600 hover:bg-indigo-700 shadow-xl shadow-indigo-600/40' : 'bg-slate-800 hover:bg-slate-700 border border-white/5'}`}
