import React, { useState, useEffect, useRef } from 'react';
import { createRoot } from 'react-dom/client';
import { PRICING_PLANS, PAYMENT_METHODS, CONTACT_NUMBER, SOCIAL_LINKS } from './constants';
import { ServiceType, OrderDetails, ChatMessage } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'home' | 'order' | 'pricing'>('home');
  const [selectedPlan, setSelectedPlan] = useState<ServiceType | null>(null);
  const [orderDetails, setOrderDetails] = useState<Partial<OrderDetails>>({
    paymentMethod: 'BKASH',
    paymentType: 'ADVANCE',
  });
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState('');
  const [isChatLoading, setIsChatLoading] = useState(false);
  const [isOrderSubmitted, setIsOrderSubmitted] = useState(false);

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory]);

  const handleSendMessage = async () => {
    if (!userInput.trim()) return;

    const newUserMsg: ChatMessage = { role: 'user', text: userInput };
    setChatHistory(prev => [...prev, newUserMsg]);
    setUserInput('');
    setIsChatLoading(true);

    const response = await getGeminiResponse(chatHistory, userInput);
    const aiMsg: ChatMessage = { role: 'model', text: response };
    setChatHistory(prev => [...prev, aiMsg]);
    setIsChatLoading(false);
  };

  const getPrice = () => {
    const plan = PRICING_PLANS.find(p => p.id === selectedPlan);
    return plan?.price || 0;
  };

  const totalAmount = getPrice();
  const payableAmount = orderDetails.paymentType === 'ADVANCE' ? totalAmount * 0.5 : totalAmount;

  const handleOrderSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const plan = PRICING_PLANS.find(p => p.id === selectedPlan);

    const waMessage = `🚀 *New Order from Mr Bangla Studio* 🚀
-------------------------------------------
👤 *অর্ডার ডিটেইলস:*
📦 প্যাকেজ: ${plan?.title}
💰 মোট মূল্য: ৳${totalAmount}
💳 পেমেন্ট মেথড: ${orderDetails.paymentMethod}
💸 পেমেন্ট টাইপ: ${orderDetails.paymentType === 'ADVANCE' ? '৫০% অগ্রিম (৳' + payableAmount + ')' : 'ফুল পেমেন্ট (৳' + totalAmount + ')'}
🧾 TrxID: ${orderDetails.trxId || 'N/A'}

-------------------------------------------
📎 *আমি এখনই আমার ভিডিও ফুটেজ (ডকুমেন্ট হিসেবে) এবং পেমেন্ট স্ক্রিনশট নিচে পাঠিয়ে দিচ্ছি। অনুগ্রহ করে চেক করুন।*`;

    const encodedMsg = encodeURIComponent(waMessage);
    const waUrl = `https://wa.me/88${CONTACT_NUMBER.replace('-', '')}?text=${encodedMsg}`;

    window.open(waUrl, '_blank');
    setIsOrderSubmitted(true);
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-100 selection:bg-indigo-500/30 font-['Inter']">
      {/* Cinematic Animated Background */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none z-0">
        <div className="absolute top-[-20%] left-[-10%] w-[60%] h-[60%] bg-indigo-600/10 blur-[150px] rounded-full animate-pulse" />
        <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-rose-600/10 blur-[150px] rounded-full animate-pulse" style={{ animationDelay: '3s' }} />
        <div className="absolute top-[30%] left-[40%] w-[30%] h-[30%] bg-emerald-600/5 blur-[120px] rounded-full animate-pulse" style={{ animationDelay: '5s' }} />
      </div>

      {/* Modern Navigation */}
      <nav className="sticky top-0 z-50 glass-panel border-b border-white/5 px-8 py-5 flex justify-between items-center transition-all duration-300">
        <div className="flex items-center gap-4 group cursor-pointer" onClick={() => setActiveTab('home')}>
