import { GoogleGenAI } from "@google/genai";
import { ChatMessage } from "../types";
import { CONTACT_NUMBER, SOCIAL_LINKS } from "../constants";

export const getGeminiResponse = async (history: ChatMessage[], message: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history.map(h => ({ role: h.role, parts: [{ text: h.text }] })),
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `তুমি "Mr Bangla Studio"-এর একজন স্মার্ট এবং প্রিমিয়াম সেলস ম্যানেজার।

        নতুন প্রাইসিং ও সার্ভিস আপডেট:
        1. স্ট্যান্ডার্ড ভাইরাল (৳৫০০): রিলস/শর্টস-এর জন্য প্রফেশনাল কাট ও কালার।
        2. প্রিমিয়াম ক্রিয়েটর (৳৮০০): ভাইরাল ক্যাপশন, VFX এবং সাউন্ড ডিজাইন। (এটি বেশি সাজেস্ট করবে)।
        3. ইভেন্ট/ওয়েডিং স্পেশাল (৳১০০০): বিয়ে বা জন্মদিনের সিনেমাটিক এডিটিং।
        4. কাস্টম এলিট (৳১৫০০+): বড় ইউটিউব ভিডিও বা স্পেশাল প্রজেক্ট।

        গুরুত্বপূর্ণ নিয়ম:
        - কাস্টমারকে ৫০০ টাকার নিচে কোনো কাজ অফার করবে না। 
        - ৫০০ টাকার প্যাকেজটি এন্ট্রি লেভেল, কিন্তু ৮০০ টাকার ভাইরাল প্যাকটি সবচেয়ে জনপ্রিয়।
        - অর্ডারের জন্য ৫০% অগ্রিম বাধ্যতামূলক।
        - ডেলিভারি সময় প্যাকেজ অনুযায়ী ২-৫ দিন।
        - পেমেন্টের পর TrxID নিয়ে হোয়াটসঅ্যাপে রিডাইরেক্ট হতে বলবে।`,
      },
    });
    return response.text || "দুঃখিত, আমি এই মুহূর্তে উত্তর দিতে পারছি না।";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "একটি ত্রুটি ঘটেছে। অনুগ্রহ করে আমাদের হোয়াটসঅ্যাপে যোগাযোগ করুন: " + CONTACT_NUMBER;
  }
};

