import { GoogleGenAI } from "@google/genai";
import { ChatMessage } from "../types";
import { CONTACT_NUMBER, SOCIAL_LINKS, YT_SUBSCRIBERS } from "../constants";

export const getGeminiResponse = async (history: ChatMessage[], message: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history.map(h => ({ role: h.role, parts: [{ text: h.text }] })),
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `তুমি "Mr Bangla Studio"-এর একজন এলিট সেলস ম্যানেজার।

        আমাদের সবচেয়ে বড় শক্তি: 
        - আমাদের একটি ভেরিফাইড এবং বিশ্বস্ত ইউটিউব চ্যানেল আছে যার বর্তমান সাবস্ক্রাইবার সংখ্যা ${YT_SUBSCRIBERS} (১ লক্ষ ২৪ হাজার+)। 
        - আমরা দীর্ঘকাল ধরে বিশ্বস্ততার সাথে কন্টেন্ট ক্রিয়েটরদের ভিডিও ভাইরাল করতে সাহায্য করছি।

        সার্ভিস আপডেট:
        1. স্ট্যান্ডার্ড ভাইরাল (৳৫০০): প্রফেশনাল Lumetri কালার ও Kinetic কাট।
        2. প্রিমিয়াম ক্রিয়েটর (৳৮০০): হরমোজি স্টাইল ভাইরাল ক্যাপশন, VFX এবং সাউন্ড ডিজাইন।
        3. ইভেন্ট/ওয়েডিং সিনেমাটিক (৳১০০০): বিয়ে বা জন্মদিনের সিনেমাটিক স্টোরিটেলিং।
        4. এলিট মেগা প্রজেক্ট (৳১৫০০+): বড় ইউটিউব ভিডিও বা কমার্শিয়াল কাজ।

        কথোপকথনের নিয়ম:
        - সবসময় ১ লক্ষ ২৪ হাজার সাবস্ক্রাইবার এবং ভেরিফাইড চ্যানেলের কথা উল্লেখ করবে যাতে কাস্টমার বিশ্বাস পায়।
        - ৫০০ টাকার নিচে কোনো কাজ অফার করবে না।
        - পেমেন্টের জন্য ৫০% অগ্রিম বাধ্যতামূলক।
        - কাস্টমারকে পেমেন্টের পর TrxID নিয়ে হোয়াটসঅ্যাপে আসতে বলবে।`,
      },
    });
    return response.text || "দুঃখিত, আমি এই মুহূর্তে উত্তর দিতে পারছি না।";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "একটি ত্রুটি ঘটেছে। আমাদের ভেরিফাইড টিমের সাথে হোয়াটসঅ্যাপে যোগাযোগ করুন: " + CONTACT_NUMBER;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { createRoot } from 'react-dom/client';
import { PRICING_PLANS, PAYMENT_METHODS, CONTACT_NUMBER, SOCIAL_LINKS, LIVE_ACTIVITIES, YT_SUBSCRIBERS, YT_CHANNEL_NAME } from './constants';
import { ServiceType, OrderDetails, ChatMessage } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'home' | 'order' | 'pricing'>('home');
  const [selectedPlan, setSelectedPlan] = useState<ServiceType | null>(null);
  const [orderDetails, setOrderDetails] = useState<Partial<OrderDetails>>({
    paymentMethod: 'BKASH',
    paymentType: 'ADVANCE',
  });
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState('');
  const [isChatLoading, setIsChatLoading] = useState(false);
  const [currentActivityIndex, setCurrentActivityIndex] = useState(0);
  const [showTicker, setShowTicker] = useState(false);

  const chatEndRef = useRef<HTMLDivElement>(null);

  // Top-Down Notification Ticker Logic
  useEffect(() => {
    const timer = setInterval(() => {
      setShowTicker(true);
      setCurrentActivityIndex(prev => (prev + 1) % LIVE_ACTIVITIES.length);

      // Hide after 5 seconds
      setTimeout(() => setShowTicker(false), 5000);
    }, 10000);

    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory]);

  const handleSendMessage = async () => {
    if (!userInput.trim()) return;
    const newUserMsg: ChatMessage = { role: 'user', text: userInput };
    setChatHistory(prev => [...prev, newUserMsg]);
    setUserInput('');
    setIsChatLoading(true);
    const response = await getGeminiResponse(chatHistory, userInput);
    setChatHistory(prev => [...prev, { role: 'model', text: response }]);
    setIsChatLoading(false);
  };

  const totalAmount = PRICING_PLANS.find(p => p.id === selectedPlan)?.price || 0;
  const payableAmount = orderDetails.paymentType === 'ADVANCE' ? totalAmount * 0.5 : totalAmount;

  const handleOrderSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const plan = PRICING_PLANS.find(p => p.id === selectedPlan);
    const waMessage = `✨ *New Order: Mr Bangla Studio* ✨
-------------------------------------------
👤 *অর্ডার ডিটেইলস:*
